draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // bird
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 - 20, H/2 + 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 30);
  ctx.lineTo(W/2 + 20, H/2 + 40);
  ctx.stroke();

  // wings
  ctx.beginPath();
  ctx.moveTo(W/2 - 20, H/2 + 40);
  ctx.lineTo(W/2 - 40, H/2 + 20 + 20 * Math.sin(t));
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 20, H/2 + 40);
  ctx.lineTo(W/2 + 40, H/2 + 20 + 20 * Math.sin(t));
  ctx.stroke();

  ctx.restore();
}
